npx --yes --package @playwright/cli playwright-cli goto http://localhost:5173/ > $null 2>&1
npx --yes --package @playwright/cli playwright-cli eval "() => { const btn = document.querySelector('.btn-row .btn'); const chain = []; let n = btn; while (n && n !== document.body) { const r = n.getBoundingClientRect(); const cs = getComputedStyle(n); chain.push(n.tagName + '|' + String(n.className && n.className.baseVal !== undefined ? n.className.baseVal : n.className).slice(0,60) + '|l=' + Math.round(r.left) + '|w=' + Math.round(r.width) + '|disp=' + cs.display); n = n.parentElement; } const bcs = getComputedStyle(btn); return 'BTN: ' + chain.join(' < ') + ' || btnW=' + bcs.width + ' ml=' + bcs.marginLeft + ' parentW=' + btn.parentElement.getBoundingClientRect().width; }" > $null 2>&1
